    /**
     * Method to retrieve the Asset via AssetFetchOneSummary
     * @param 	summary AssetFetchOneSummary 
     * @return 	AssetFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Asset getAsset( AssetFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "AssetFetchOneSummary arg cannot be null" );
    	
    	Asset entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Asset
        	// --------------------------------------
        	CompletableFuture<Asset> futureEntity = queryGateway.query(new FindAssetQuery( new LoadAssetFilter( summary.getAssetId() ) ), ResponseTypes.instanceOf(Asset.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Asset with id " + summary.getAssetId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


