    /**
     * assign Plant on Asset
     * @param		command AssignPlantToAssetCommand	
     * @exception	ProcessingException
     */     
	public void assignPlant( AssignPlantToAssetCommand command ) throws ProcessingException {

		// --------------------------------------------
		// load the parent
		// --------------------------------------------
		load( command.getAssetId() );
		
		PlantService childDelegate 	= PlantService.getPlantInstance();
		AssetService parentDelegate = AssetService.getAssetInstance();			
		UUID childId = command.getAssignment().getPlantId();
		Plant child = null;
		
		try {
			// --------------------------------------
	    	// best to validate the command now
	    	// --------------------------------------    
	    	validator.validate( command );    

	    	// --------------------------------------
        	// issue the command
        	// --------------------------------------    	
    		commandGateway.sendAndWait( command );

		}
        catch( Throwable exc ) {
			final String msg = "Failed to get Plant using id " + childId;
			LOGGER.log( Level.WARNING,  msg );
			throw new ProcessingException( msg, exc );
        }
	}

